package com.whaa.shop.statistics.controller;
import com.whaa.shop.common.api.ApiResponse;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.web.bind.annotation.*;import java.math.BigDecimal;import java.util.*;
@RestController @RequestMapping("/api/v1/admin/statistics") public class StatisticsController {private final JdbcTemplate jdbc;public StatisticsController(JdbcTemplate jdbc){this.jdbc=jdbc;}@GetMapping("/dashboard")ApiResponse<Dashboard> dashboard(){BigDecimal sales=value("select coalesce(sum(total_amount),0) from shop_order where status in ('PAID','SHIPPED','COMPLETED')",BigDecimal.class);long orders=value("select count(*) from shop_order",Long.class);long users=value("select count(*) from shop_user where role='USER'",Long.class);double rating=value("select coalesce(avg(rating),0) from product_review where hidden=0",Double.class);long todayOrders=value("select count(*) from shop_order where date(created_at)=current_date",Long.class);long publishedProducts=value("select count(*) from product where published=1",Long.class);List<Map<String,Object>> hotProducts=jdbc.queryForList("select name,sales from product where published=1 order by sales desc limit 8");List<Map<String,Object>> trend=jdbc.queryForList("select date(created_at) day,count(*) orders,coalesce(sum(total_amount),0) sales from shop_order where created_at>=date_sub(current_date,interval 6 day) group by date(created_at) order by day");List<Map<String,Object>> orderStatus=jdbc.queryForList("select status,count(*) value from shop_order group by status order by value desc");List<Map<String,Object>> categorySales=jdbc.queryForList("select c.name,coalesce(sum(p.sales),0) value from category c left join product p on p.category_id=c.id and p.published=1 where c.enabled=1 group by c.id,c.name order by value desc limit 8");List<Map<String,Object>> userTrend=jdbc.queryForList("select date(created_at) day,count(*) users from shop_user where role='USER' and created_at>=date_sub(current_date,interval 6 day) group by date(created_at) order by day");return ApiResponse.ok(new Dashboard(sales,orders,users,Math.round(rating*10)/10.0,todayOrders,publishedProducts,hotProducts,trend,orderStatus,categorySales,userTrend));}private<T>T value(String sql,Class<T> type){return jdbc.queryForObject(sql,type);}public record Dashboard(BigDecimal sales,long orders,long users,double rating,long todayOrders,long publishedProducts,List<Map<String,Object>> hotProducts,List<Map<String,Object>> trend,List<Map<String,Object>> orderStatus,List<Map<String,Object>> categorySales,List<Map<String,Object>> userTrend){}
}
